/*
 * mst_$set_mstes - fill the MSTEs of segments [start, end] of an ASID
 *
 * Original address: 0x00E43E10, 304 bytes (0x00E43E10 .. 0x00E43F3F)
 * Module-local routine of MST_UNWIRED, no map symbol (was FUN_00e43e10).
 * Generated by: Claude Opus 5.5
 *
 * Callers: MST_$MAP_CANNED (0x00E30F7C), MST_$MAP_CANNED_AT (0x00E31086)
 * and mst_$alloc_segs (0x00E4357A).  Frame (link.w A6,-0x1C; D2-D7/A2-A3/A5
 * saved; A5 = 0xE7CF0C, unused):
 *   (0x08,A6) uid         longword pointer
 *   (0x0C,A6) obj_seg     word  (D3w) object segment of the first MSTE
 *   (0x0E,A6) location    longword, the MSTE location word
 *   (0x12,A6) start       word  (D2w) first ASID-relative segment
 *   (0x14,A6) end         word  (D4w) last one
 *   (0x16,A6) touch_count word, only its low byte (0x17) is read
 *   (0x18,A6) asid        word
 *   (0x1A,A6) prot        word  (D0w)
 *   (0x1C,A6) wired       byte in the high half of its word slot (D6b)
 *
 * Blocks:
 *   0x00E43E36-0x00E43E74  MSTE of `start`: MST_PAGE_TABLE_BASE +
 *                          (MST[MST_ASID_BASE[asid] + (start >> 6)] - 1) *
 *                          0x400 + (start & 0x3F) * 16
 *   0x00E43E78-0x00E43EC4  fill it: UID, obj_seg, flags word (+0x0A: bit 15
 *                          `wired`, bits 9..14 (prot | 2) << 1 of the high
 *                          byte, the rest cleared - bit 8 survives the first
 *                          two masks but not the `andi.w #-0x200`), location
 *                          with (touch_count - 1) in bits 26..30
 *   0x00E43EC6-0x00E43F2E  copy it to the following MSTEs up to `end`, one
 *                          page-table page at a time, each with the next
 *                          object segment
 *   0x00E43F30             CACHE_$CLEAR
 */

#include "mst/mst_internal.h"
#include "cache/cache.h"

/* `ori.w #0x2,D0w` 0x00E43E36 */
#define MST_SET_PROT_OR         0x0002
/* MSTEs per page-table page: `moveq #0x3f` masks, `moveq #0x40` 0x00E43EC8 */
#define MST_SET_SEG_MASK        0x3F
#define MST_SET_SEGS_PER_PAGE   0x40

/* The MSTE of ASID-relative segment `seg` (word arithmetic as in the image). */
static mste_t *mst_$set_mstes_entry(uint16_t asid_base, uint16_t seg)
{
    uint16_t page = MST[(uint16_t)((seg >> 6) + asid_base)];

    return (mste_t *)ARCH_VA_TO_PTR(MST_PAGE_TABLE_BASE + (uint32_t)page * 0x400u +
                                    (uint32_t)(seg & MST_SET_SEG_MASK) * 0x10u -
                                    0x400u);
}

void mst_$set_mstes(uid_t *uid, uint16_t obj_seg, uint32_t location,
                    uint16_t start, uint16_t end, uint16_t touch_count,
                    uint16_t asid, uint16_t prot, int8_t wired)
{
    mste_t *first;          /* A0 - 0x400 */
    mste_t *dst;            /* A1 */
    uint16_t asid_base;     /* D5w */
    uint16_t seg;           /* D1w */
    uint16_t last;          /* D2w */
    int16_t n;              /* D0w */
    uint8_t hi;

    /* 0x00E43E36-0x00E43E74 */
    prot |= MST_SET_PROT_OR;
    asid_base = MST_ASID_BASE[asid];
    first = mst_$set_mstes_entry(asid_base, start);

    /* 0x00E43E78-0x00E43E80 */
    first->uid = *uid;
    first->segment = obj_seg;

    /* 0x00E43E84-0x00E43EA2: the high byte of the word at +0x0A is masked
     * with 0x3F then 0xC1, OR'd with the low byte of prot shifted left one,
     * then the word is masked with 0xFE00. */
    hi = (uint8_t)(first->unknown_0a >> 8);
    hi &= 0x3F;
    hi &= 0xC1;
    hi |= (uint8_t)((uint8_t)prot << 1);
    first->unknown_0a = (uint16_t)(((uint16_t)hi << 8) | (first->unknown_0a & 0x00FFu));
    first->unknown_0a &= 0xFE00u;
    if (wired < 0) {
        first->unknown_0a |= 0x8000u;
    }

    /* 0x00E43EA8-0x00E43EC0: location, then (touch_count - 1) << 2 into
     * bits 2..6 of its high byte (`andi.b #-0x7d` keeps 0x83) */
    first->location = location;
    hi = (uint8_t)(first->location >> 24);
    hi &= 0x83;
    hi |= (uint8_t)((uint8_t)((uint8_t)touch_count - 1) << 2) & 0x7C;
    first->location = (first->location & 0x00FFFFFFu) | ((uint32_t)hi << 24);

    /* 0x00E43EC4 bra 0x00E43F28; 0x00E43EC6-0x00E43F2E */
    last = start;
    for (seg = (uint16_t)(last + 1); seg <= end; seg = (uint16_t)(last + 1)) {
        /* 0x00E43EC6-0x00E43ED6: to the end of this page-table page, or end */
        last = (uint16_t)(seg + MST_SET_SEGS_PER_PAGE - (seg & MST_SET_SEG_MASK) - 1);
        if (end < last) {
            last = end;
        }

        /* 0x00E43ED8-0x00E43F24 */
        dst = mst_$set_mstes_entry(asid_base, seg);
        for (n = (int16_t)(last - seg); n >= 0; n--) {
            *dst = *first;
            obj_seg++;
            dst->segment = obj_seg;
            dst++;
        }
    }

    /* 0x00E43F30 */
    CACHE_$CLEAR();
}
